..now you just need to iterate through the input newlines and indent with `indent` string, first line if `first` is true and blank lines if `blank` is true.

```suggestion

    test_template(t, "indent",
        "{{ data|indent }}",
        { "data", "foo\n\nbar" },
        "foo\n\n    bar"
    );

    test_template(t, "indent first",
        "{{ data|indent(2, first=true) }}",
        { "data", "\n\nbar" },
        "  \n\n  bar"
    );

    test_template(t, "indent blank",
        "{{ data|indent('  ', blank=true) }}",
        { "data", "foo\n\nbar" },
        "foo\n  \n  bar"
    );
